import { callTool, listTools } from './server.mjs';

const checks = [];
const expectReject = async (fn, msg) => {
  try { await fn(); checks.push('NO REJECT: ' + msg); }
  catch (e) { checks.push('ok reject: ' + msg); }
};

// listTools returns 3 tools with additionalProperties:false
const tools = await listTools();
checks.push('tool count: ' + tools.length);
checks.push('all additionalProperties false: ' + tools.every(t => t.inputSchema.additionalProperties === false));

// unknown tool
await expectReject(() => callTool('nope', {}), 'unknown tool');

// begin_session requires non-empty string session_id
await expectReject(() => callTool('begin_session', {}), 'missing session_id');
await expectReject(() => callTool('begin_session', { session_id: '' }), 'empty session_id');
await expectReject(() => callTool('begin_session', { session_id: 's1', extra: 1 }), 'extra arg');

// put before session -> reject (missing session)
await expectReject(() => callTool('put_value', { session_id: 'ghost', key: 'k', value: 'v' }), 'missing session');

await callTool('begin_session', { session_id: 's1' });

// put requires key, value
await expectReject(() => callTool('put_value', { session_id: 's1', key: 'k' }), 'missing value');
await expectReject(() => callTool('put_value', { session_id: 's1', key: '', value: 'v' }), 'empty key');
await expectReject(() => callTool('put_value', { session_id: 's1', key: 'k', value: 5 }), 'non-string value');
await expectReject(() => callTool('put_value', { session_id: 's1', key: 'k', value: 'v', foo: 1 }), 'extra arg');

await callTool('put_value', { session_id: 's1', key: 'k', value: 'one' });
const got = await callTool('get_value', { session_id: 's1', key: 'k' });
checks.push('get s1 k: ' + got.content[0].text);

// isolation: s2 can't read
await callTool('begin_session', { session_id: 's2' });
await expectReject(() => callTool('get_value', { session_id: 's2', key: 'k' }), 's2 cannot read s1 key');

// get requires args
await expectReject(() => callTool('get_value', { session_id: 's1' }), 'missing key');
await expectReject(() => callTool('get_value', { session_id: 's1', key: 'k', extra: 1 }), 'get extra arg');

console.log(checks.join('\n'));
""}

